        return Q(*(x / n2 for x in self.conjugate())) 
 
    def __str__(self):
        'Shorter form of Quaternion as string'
        return 'Q(%g, %g, %g, %g)' % self
 
    def __neg__(self):
        return Q(-self.real, -self.i, -self.j, -self.k)
 
