   public WindowController() {
      super( "Controller" );
 
      final JPanel main = new JPanel();
      final JPanel controls = new JPanel();
 
      setLocationByPlatform( true );
      setResizable( false );
      setDefaultCloseOperation( JFrame.EXIT_ON_CLOSE );
