    public static void main(String[] args) {
        int num, len;
 
        try {
            if (args.length != 2)
                throw new IllegalArgumentException();
 
            len = Integer.parseInt(args[0]);
            if (len < 4 || len > 16)
                throw new IllegalArgumentException();
 
            num = Integer.parseInt(args[1]);
            if (num < 1 || num > 10)
                throw new IllegalArgumentException();
 
            for (String pw : generatePasswords(num, len))
