import static java.util.stream.Collectors.toList;
 
import java.util.List;
 
public class CartesianProduct {
 
    public List<?> product(List<?>... a) {
        if (a.length >= 2) {
            List<?> product = a[0];
            for (int i = 1; i < a.length; i++) {
