        for x in m:
            print " ".join("x#.?"[i] for i in x)
        print
 
    w, h = len(vr), len(hr)
    rows = [gen_row(w, x) for x in hr]
    cols = [gen_row(h, x) for x in vr]
    can_do = map(allowable, rows)
 
    # Initially mark all columns for update.
    mod_rows, mod_cols = set(), set(xrange(w))
 
    while mod_cols:
        for i in mod_cols:
            fix_col(i)
        mod_cols = set()
        for i in mod_rows:
