            observation[j] = x;
            magnitude = x * x;
        }
 
        // normalize
        const magnitude = Math.sqrt(magnitude);
        for(let j = 0; j < d; j += 1) {
            observation[j] /= magnitude;
        }
 
        return observation;
    }
 
    /**
