public class Comb{
 
        public static void main(String[] args){
                System.out.println(comb(3,5));
        }
 
        public static String bitprint(int u){
                String s= "";
                for(int n= 0;u > 0;++n, u>>= 1)
                        if((u & 1) > 0) s+= n + " ";
                return s;
        }
 
