        if (grid[r][c] == 0 && nextClue < clues.length)
            if (clues[nextClue] == count)
                return false;
 
        int back = grid[r][c];
        if (back == count)
            nextClue++;
 
        grid[r][c] = count;
        for (int[] move : moves)
            if (solve(r + move[1], c + move[0], count + 1, nextClue))
                return true;
 
        grid[r][c] = back;
        return false;
    }
 
