public class GeneratorExponential implements LongSupplier {
    private LongSupplier source, filter;
    private long s, f;
 
    public GeneratorExponential(LongSupplier source, LongSupplier filter) {
        this.source = source;
        this.filter = filter;
        f = filter.getAsLong();
