        function HSVtoRGB(h, s, v) {
            var r, g, b, i, f, p, q, t;
 
            i = Math.floor(h * 6);
            f = h * 6 - i;
            p = v * (1 - s);
            q = v * (1 - f * s);
            t = v * (1 - (1 - f) * s);
